programs.haiku:
"""A weak, word-level guess at one layer-15 MLP unit's contribution.

This component is MLP hidden unit 4619 of layer 15 (its direction is about 0.5 on that unit,
the rest spread thinly over others). Its activation is mostly diffuse: no token or simple
context explains much of it. The few cues that shift it on average are word-level:
  * "of" right after "type(s)" / "kind(s)" (as in "different types of adhesives"): high, +0.24;
  * quantifiers and distributives ("each", "both", "two", "all"): mildly positive, +0.13;
  * hedging quantifiers ("most", "some", "many", "various", "certain"): mildly negative, -0.15;
  * everything else: -0.01, the component's mean.
"""

READS = ()

TYPE_NOUNS = {"type", "types", "kind", "kinds", "sort", "sorts", "variety"}
QUANTIFIERS = {"each", "both", "two", "three", "all", "every", "either"}
HEDGES = {"most", "some", "such", "many", "various", "certain", "perhaps"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_ids) > 1 else ""
    if cur == "of" and prev in TYPE_NOUNS:
        return carry, 0.24
    if cur in QUANTIFIERS:
        return carry, 0.13
    if cur in HEDGES:
        return carry, -0.15
    return carry, -0.01

"""Layer 15 MLP down_proj component 4646: a weak 'totality / superlative scope' feature.

The component's activation is mostly one MLP hidden unit (4646) times a fixed readout.
That unit's gate opens on function words that begin a scope or range phrase, and its sign
comes from the up projection. Its most negative values fall on words that close a totality
phrase ("ever", "entire", "all", "total", "possible"), on "the / in / of / on" inside a
superlative phrase ("the best ... in the [world]"), and on a loop's comparison and index
tokens in code ("for (i = 0; i [<] n"). Its positive values are weak and mostly on the
digits of years.

This program reproduces only that coarse pattern, with weights fitted by least squares on
training activations. It explains very little of the variance; it is a readable sketch.
"""

READS = ()

SUPERLATIVES = {"best", "most", "highest", "largest", "lowest", "worst", "greatest",
                "biggest", "smallest", "finest", "least"}
SCOPE_WORDS = {"ever", "entire", "all", "whole", "total", "every", "any", "possible",
               "available"}
SCOPE_FUNCTION = {"the", "in", "of", "on"}
LOOP_TOKENS = {"<", "<=", "=", "i", "n", ">=", "+"}
LOOP_WORDS = {"for", "while"}
WINDOW = 8
LOOP_WINDOW = 10


def _word(s):
    return s.strip().lower()


def _is_superlative(w):
    return w in SUPERLATIVES or (w.endswith("est") and len(w) > 4)


def step(carry, prefix, upstream):
    doc = prefix.document_ids
    n = len(doc)
    word = _word(prefix.token_strings[-1])
    # Same-document words just before this token.
    recent = [
        _word(prefix.token_strings[i])
        for i in range(max(0, n - 1 - LOOP_WINDOW), n - 1)
        if doc[i] == doc[-1]
    ]
    superlative_nearby = any(_is_superlative(w) for w in recent[-WINDOW:])
    loop_nearby = any(w in LOOP_WORDS for w in recent)
    value = 0.0
    if word in SCOPE_WORDS:
        value -= 0.3
        if superlative_nearby:
            value -= 1.1
    elif word in SCOPE_FUNCTION and superlative_nearby:
        value -= 0.4
    elif word in LOOP_TOKENS and loop_nearby:
        value -= 0.4
    elif word.isdigit() and n > 1 and prefix.token_strings[-2].strip() in ("1", "2"):
        value += 0.03
    return carry, value

"""Layer 15 MLP unit 4647 (component 4647 of down_proj), read as a word-level program.

What it does: this component writes almost only the activation of one MLP hidden unit,
and its output points at "type"-style words. In the text it lights up inside phrases that
introduce a SET OF KINDS or a MEMBER OF A SET:
  - set-introducing quantifiers and adjectives: other, another, different, various,
    two, three, these, both, major, main, basic, important ...
    strongest when they open a noun phrase ("any other", "a different", "the most important");
    weaker when used predicatively ("is important", "is different") or after "each" (each other);
  - category nouns: type, kind, category, aspect, factor, method, form, part ...
  - "of" right after such a noun ("types of", "kinds of", "a variety of");
  - "the" in "one of the ...".
Everywhere else it is near zero. Values are the mean activations of each class, fitted on
training rows; the program ignores everything else, so most of its variance is unexplained.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

QUANTIFIERS = {
    "other", "another", "different", "various", "several", "both", "these", "those",
    "two", "three", "four", "diverse", "certain", "whatever", "alternative", "multiple",
    "many", "such", "few",
}
SET_ADJECTIVES = {
    "major", "main", "primary", "key", "basic", "important", "fundamental", "essential",
    "crucial", "popular", "favorite", "greatest", "largest", "highest", "common", "special",
    "specific", "principal", "relevant", "powerful", "biggest", "unusual", "interesting",
    "latter", "next", "additional", "distinct",
}
CATEGORY_NOUNS = {
    "type", "types", "kind", "kinds", "category", "categories", "aspect", "aspects",
    "factor", "factors", "method", "methods", "component", "components", "class", "classes",
    "feature", "features", "characteristic", "characteristics", "technique", "techniques",
    "mechanism", "mechanisms", "topic", "topics", "concept", "concepts", "variety",
    "varieties", "form", "forms", "area", "areas", "part", "parts", "element", "elements",
    "group", "groups", "domain", "domains",
}
# words that open a noun phrase, so a modifier after them is attributive
OPENERS = {
    "the", "a", "an", "these", "those", "any", "some", "no", "most", "this", "that", "its",
    "their", "his", "her", "our", "your", "of", "in", "from", "for", "by", "on", "among",
    "between", "to", "than", "or", "several", "many", "all", "both", "one", "two", "three",
    "such", "very", "with", "at", "into", "across", "within", "through", "about",
}
# copulas and "each": a modifier after these is predicative (is important) or reciprocal
PREDICATIVE = {
    "is", "are", "be", "was", "were", "been", "being", "'s", "’s", "am", "so", "also",
    "seems", "become", "becomes", "much", "quite", "very", "more", "each", "exactly",
    "have", "has", "had", "just",
}
MODIFIERS = QUANTIFIERS | SET_ADJECTIVES


def _word(prefix, back):
    """The token `back` places before the newest one, in the same document, or ''."""
    i = len(prefix.token_strings) - 1 - back
    if i < 0 or prefix.document_ids[i] != prefix.document_ids[-1]:
        return ""
    return prefix.token_strings[i].strip().lower()


def step(carry, prefix, upstream: Mapping):
    word = _word(prefix, 0)
    prev = _word(prefix, 1)
    prev2 = _word(prefix, 2)
    if word in MODIFIERS:
        if prev in {"these", "those"} and word in {"two", "three", "four"}:
            return carry, 4.0
        if prev in PREDICATIVE:
            return carry, 0.9
        if prev in OPENERS:
            return carry, 1.8
        return carry, 0.8
    if word in CATEGORY_NOUNS:
        return carry, 0.7
    if word == "of" and prev in CATEGORY_NOUNS:
        return carry, 2.0
    if word == "of" and prev in {"one", "two", "three", "some", "most"}:
        return carry, 1.0
    if word == "the" and prev == "of" and prev2 == "one":
        return carry, 2.5
    return carry, 0.0

"""Layer 15, MLP hidden unit 4661 (component 4661 of layers.15.mlp.down_proj).

The component's read vector is almost entirely that one SwiGLU hidden unit, so its activation
is a signed, high-variance number. Most of the variance is context that simple features
do not capture (the token's identity, its surprisal, repetition and attention-style copying
all explain almost none of it). This program predicts only the coarse trends that do show up:

- 0 at a document's first token, where the activation is essentially zero;
- negative (about -0.4) on a token that continues a word begun earlier, when that word is
  rare in English (wordfreq zipf < 3), which includes runs of CJK characters;
- negative (about -0.28) on a single CJK character;
- slightly negative (about -0.25) in the first 12 tokens of a document;
- 0 otherwise.

Its values are group means, so it explains about 1% of the variance.
"""
import regex
from wordfreq import zipf_frequency

READS = ()

CJK = regex.compile(r"[\p{Han}\p{Hiragana}\p{Katakana}\p{Hangul}]")
LETTERS = regex.compile(r"\p{L}+")


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tok = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        pos, word, pieces = 0, "", 0
    else:
        pos, word, pieces = carry[1] + 1, carry[2], carry[3]
    # the word so far: letters since the last word-initial token
    if tok[:1] in (" ", "\n", "\t") or not LETTERS.fullmatch(tok):
        stripped = tok.strip()
        word = stripped if LETTERS.fullmatch(stripped or "x") else ""
        pieces = 1
    else:
        word += tok
        pieces += 1
    if pos == 0:
        value = 0.0
    elif CJK.search(tok):
        value = -0.28
    elif pieces >= 2 and zipf_frequency(word, "en") < 3:
        value = -0.4
    elif pos < 12:
        value = -0.25
    else:
        value = 0.0
    return (doc, pos, word, pieces), value

"""Draft 4: code idioms that push this component's activation up or down.

Activity is strongest in code. Three things move it most:
- the opening bracket of a control statement ("if (", "for (", "catch (", "try {"): strongly negative;
- an open bracket that ends a line, opening a call's argument list ("foo(\\n"): strongly positive;
- the end-of-text token: negative.
Indentation at the start of a line is weakly signed by the line before it, and
everything else is near zero.
"""
READS = ()

# Mean activation after each block keyword, as measured on the training rows.
CONTROL = {"for": -14.0, "foreach": -12.0, "catch": -12.0, "while": -10.0,
           "switch": -10.0, "if": -7.0}
OPEN = ("(", "{", "($", "((")
CALL_OPEN_NEWLINE = 11.0
END_OF_TEXT = -3.2


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    same_doc = len(toks) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = toks[-2] if same_doc else ""
    prev_end = prev.rstrip()[-1:]  # last visible character of the previous token
    line_start = "\n" in prev and cur.strip() == "" and cur != ""

    if cur == "<|endoftext|>":
        return carry, END_OF_TEXT
    if cur.lstrip() in OPEN and prev.strip() in CONTROL:
        return carry, CONTROL[prev.strip()]
    if cur in ("(\n", " (\n"):
        return carry, CALL_OPEN_NEWLINE
    if line_start:
        if prev_end == ")":
            return carry, -1.2
        if prev_end == "}":
            return carry, -0.7
        if prev_end == ";":
            return carry, 0.1
        return carry, -0.4
    if cur == " of":
        return carry, 0.2
    return carry, 0.0

"""Forward-pointer detector (layer 15 MLP, hidden unit 4665).

This component goes negative on the word just before a reader is pointed at
something further along the text: "the following", "Here is", "in Figure 2",
"are shown", "click on the links [below]". Its output direction, read through
the unembedding, promotes "below / above / following", so a negative activation
means "a forward reference is due here". Positive or near-zero activations
elsewhere are not captured.

The program looks only at the current word and the word before it:
  - FORWARD words ("following", "below", "above", "follows"): strongly negative
    after "the/in/of/these/this", weakly negative otherwise.
  - "here" that opens a sentence or clause ("Here's ..."): strongly negative.
  - FIGURE words ("figure", "fig", "table") after "in/see/are/is/the/on":
    moderately negative.
  - SHOWN words ("shown", "illustrated", "described", ...) after "are/were/is/
    was/be/been": moderately negative.
Everything else is 0.
"""

READS = ()

FORWARD = {"following", "below", "above", "follows", "以下", "下面", "如下", "ниже"}
HERE = {"here"}
FIGURE = {"figure", "fig", "figures", "table"}
SHOWN = {"shown", "illustrated", "summarized", "discussed", "described", "listed"}

# words after which a pointer word reads as a determiner or lead-in
DETERMINER_BEFORE = {"the", "in", "of", "these", "this"}
REFERENCE_BEFORE = {"in", "see", "are", "is", "the", "on"}
PASSIVE_BEFORE = {"are", "were", "is", "was", "be", "been"}
# what counts as a sentence or clause start (the empty string is whitespace or a newline)
CLAUSE_START = {"", ".", ",", ":", "!", "?", ")", '"'}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    before = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        before = prefix.token_strings[-2].strip().lower()

    if word in FORWARD:
        value = -4.0 if before in DETERMINER_BEFORE else -1.0
    elif word in HERE:
        value = -4.0 if before in CLAUSE_START else -0.5
    elif word in FIGURE:
        value = -2.0 if before in REFERENCE_BEFORE else -0.8
    elif word in SHOWN:
        value = -2.0 if before in PASSIVE_BEFORE else -0.4
    else:
        value = 0.0
    return carry, value

"""Draft B: mostly-flat component with small dips at sentence ends, questions,
line breaks, and contrast words ("but", "however", ...)."""
import re

READS = ()

SENTENCE_END = re.compile(r"[.?!。？！]+\s*$")
QUESTION = re.compile(r"[?？]")
CONTRAST = {"but", "however", "though", "although", "yet", "still", "aber", "mais", "pero", "但", "但是", "然而"}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    value = 0.0
    if SENTENCE_END.search(s):
        value -= 0.14
    if QUESTION.search(s):
        value -= 0.07
    if "\n" in s:
        value -= 0.05
    if s.strip(" ,").lower() in CONTRAST:
        value -= 0.07
    return carry, value

"""Layer 15 MLP hidden unit 4668 (the component's activation), in plain terms.

Mostly the unit sits near 0 with a lot of small noise. Its large negative dips come on words
that say something has to be set up or adapted in advance: "trained" (can be trained on),
"fixed" (a fixed number of), "custom", "specific" (requires specific code), "predefined",
"calibrated", "tuned", "preset", "programmed". The deepest dips come when such a word follows a
cue such as be / need / require / must / can. Ordinary words sit slightly off zero: participles
(-ed, -ing, -ly) dip a little, while punctuation, newlines, digits, prepositions and determiners
sit a little above zero. CJK characters dip a little.

The program is a readable sketch of this. It explains under 1% of the variance: the activation
is spread thinly over ordinary tokens, so no short word list captures most of it.
"""

READS = ()

SETUP_STRONG = {
    "trained", "predefined", "pre-defined", "calibrated", "programmed", "preset", "pre-set",
    "optimized", "validated", "tuned", "customized", "customised", "adjustable", "tailored",
    "predetermined", "configured", "hard-coded", "specially",
}
SETUP_MEDIUM = {
    "fixed", "custom", "specific", "adapted", "adjust", "adjusted", "tuning", "learned", "learn",
    "training", "constant", "designed", "updated", "stored", "built", "created", "approved",
    "manually", "particular", "special", "dedicated", "static", "known", "specified",
}
CUE_WORDS = {"be", "is", "are", "was", "were", "been", "being", "require", "requires", "required",
             "need", "needs", "must", "can", "should", "based"}
PUNCT = set(",.;:!?()[]{}\"'`")
DETERMINERS = {"the", "a", "an"}
PREPOSITIONS = {"to", "of", "in", "for", "with", "by", "on", "from", "at", "as"}
NEGATIONS = {"not", "no", "never", "without"}
AUXILIARIES = {"is", "are", "was", "were", "be", "been", "can", "will", "would", "should", "may"}


def word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    t = prefix.position
    s = prefix.token_strings[t]
    w = word(s)
    # the three tokens before, within the same document
    before = [word(prefix.token_strings[i]) for i in range(max(0, t - 3), t)
              if prefix.document_ids[i] == prefix.document_ids[t]]
    cue = any(b in CUE_WORDS for b in before)

    if w in SETUP_STRONG:
        return carry, -1.4 - (0.7 if cue else 0.0)
    if w in SETUP_MEDIUM:
        return carry, -0.5 - (0.1 if cue else 0.0)
    if w.endswith("ed") and len(w) > 4:
        return carry, -0.12
    if w.endswith("ing") and len(w) > 5:
        return carry, -0.04
    if w.endswith("ly") and len(w) > 4:
        return carry, -0.05
    if s.strip() in PUNCT or "\n" in s:
        return carry, 0.045
    if w.isdigit():
        return carry, 0.03
    if w in PREPOSITIONS or w in DETERMINERS:
        return carry, 0.03
    if w in NEGATIONS:
        return carry, 0.04
    if w in AUXILIARIES:
        return carry, -0.02
    if any("一" <= c <= "鿿" for c in s):
        return carry, -0.035
    return carry, 0.0
